import 'dart:convert';
import 'dart:io';

import 'package:eros_app/core/constants/languages.dart';
import 'package:eros_app/features/profile/domain/enums/gender.dart';
import 'package:eros_app/features/profile/domain/enums/personality.dart';
import 'package:eros_app/features/profile/domain/enums/preferences.dart';
import 'package:eros_app/features/profile/domain/models/my_profile.dart';
import 'package:eros_app/features/profile/domain/models/update_user_request.dart';
import 'package:flutter_test/flutter_test.dart';

/// Both fixtures were generated by the backend's own serializers (`User.toDTO()` encoded with
/// Ktor's default JSON settings), so they are exactly what `GET /users/me` sends.
Map<String, dynamic> _fixture(String name) =>
    jsonDecode(File('test/fixtures/users/$name').readAsStringSync()) as Map<String, dynamic>;

void main() {
  group('MyProfile.fromJson', () {
    late MyProfile profile;

    setUp(() => profile = MyProfile.fromJson(_fixture('get_users_me.json')));

    test('reads the basic fields', () {
      expect(profile.userId, 'fixture-user');
      expect(profile.firstName, 'Ada');
      expect(profile.lastName, 'Lovelace');
      expect(profile.email, 'ada@example.com');
      expect(profile.heightCm, 170);
      expect(profile.dateOfBirth, DateTime(1995, 3, 14));
      expect(profile.city, 'London');
      expect(profile.educationLevel, EducationLevel.university);
      expect(profile.gender, Gender.female);
      expect(profile.preferredLanguage.code, 'en');
      expect(profile.coordinatesLatitude, 51.5074);
      expect(profile.coordinatesLongitude, -0.1278);
      expect(profile.occupation, 'Engineer');
      expect(profile.bio, 'Likes long walks.');
    });

    test('reads interests as display names and traits as enums', () {
      expect(profile.interests, ['Hiking', 'Nature', 'Movies', 'Photography', 'Yoga', 'Afro Beats', 'BBQ']);
      expect(profile.traits.length, 5);
      expect(profile.traits.first, Trait.adventurous);
    });

    test('reads values and show/hide flags, including nulls', () {
      expect(profile.spokenLanguages.field.map((l) => l.code), ['en', 'es']);
      expect(profile.spokenLanguages.visible, isTrue);
      expect(profile.religion.field, isNotNull);
      expect(profile.religion.visible, isFalse);
      expect(profile.politicalView.field, isNull);
      expect(profile.politicalView.visible, isFalse);
      expect(profile.dateIntentions.field, DateIntentions.seriousDating);
      expect(profile.relationshipType.field, RelationshipType.monogamous);
      expect(profile.kidsPreference.field, KidsPreference.openToKids);
      expect(profile.kidsPreference.visible, isFalse);
      expect(profile.sexualOrientation.field, SexualOrientation.straight);
      expect(profile.ethnicity.field, hasLength(1));
      expect(profile.brainAttributes.field, hasLength(2));
      expect(profile.brainDescription.field, 'Curious about everything.');
      expect(profile.bodyAttributes.field, isNull);
      expect(profile.bodyDescription.field, isNull);
    });

    test('reads completeness and verification status', () {
      expect(profile.profileCompleteness, 70);
      expect(profile.photoValidationStatus, 'PENDING');
      expect(profile.isVerified, isFalse);
    });

    test('parses a response from a backend without the PE-B1 fields', () {
      final older = _fixture('get_users_me.json')
        ..remove('profileCompleteness')
        ..remove('photoValidationStatus');

      final parsed = MyProfile.fromJson(older);

      expect(parsed.profileCompleteness, isNull);
      expect(parsed.photoValidationStatus, isNull);
      expect(parsed.isVerified, isFalse);
    });
  });

  group('a language the app does not list yet (eros-app#17)', () {
    final json = _fixture('get_users_me.json')
      ..['preferredLanguage'] = 'Hindi'
      ..['spokenLanguages'] = {'field': ['English', 'Arabic'], 'display': true};

    test('still loads, keeping the backend value', () {
      final parsed = MyProfile.fromJson(json);

      expect(parsed.preferredLanguage.isSupported, isFalse);
      expect(parsed.preferredLanguage.name, 'Hindi');
      expect(parsed.spokenLanguages.field.map((l) => l.isSupported), [true, false]);
    });

    test('is sent back unchanged when the profile is saved', () {
      final parsed = MyProfile.fromJson(json);

      final request = UpdateUserRequest(
        preferredLanguage: parsed.preferredLanguage,
        spokenLanguages: parsed.spokenLanguages,
      ).toJson();

      expect(request['preferredLanguage'], 'Hindi');
      expect(request['spokenLanguages'], {'field': ['English', 'Arabic'], 'display': true});
    });

    test('every backend language survives a load and save', () {
      final languages = (_fixture('backend_display_names.json')['language'] as List<dynamic>).cast<String>();

      expect(languages.map((name) => Language.fromBackend(name).toBackend()), languages);
    });
  });

  group('every display name the backend can send', () {
    final names = _fixture('backend_display_names.json');
    List<String> of(String key) => (names[key] as List<dynamic>).cast<String>();

    final parsers = <String, void Function(String)>{
      'gender': Gender.fromBackend,
      'educationLevel': EducationLevel.fromBackend,
      'religion': Religion.fromBackend,
      'politicalView': PoliticalView.fromBackend,
      'alcoholConsumption': AlcoholConsumption.fromBackend,
      'smokingStatus': SmokingStatus.fromBackend,
      'diet': Diet.fromBackend,
      'dateIntentions': DateIntentions.fromBackend,
      'relationshipType': RelationshipType.fromBackend,
      'kidsPreference': KidsPreference.fromBackend,
      'sexualOrientation': SexualOrientation.fromBackend,
      'pronouns': Pronouns.fromBackend,
      'starSign': StarSign.fromBackend,
      'trait': Trait.fromBackend,
      'language': LanguageCode.fromBackend,
      'ethnicity': Ethnicity.fromBackend,
      'brainAttribute': BrainAttribute.fromBackend,
      'bodyAttribute': BodyAttribute.fromBackend,
    };

    // Known gap: the backend's Language enum has 34 languages, the app's LanguageCode 12. The
    // app can only offer its own 12. A profile holding any of the other 22 still loads, as
    // Language.unsupported (tested below), but the app can't show or offer them properly.
    // Decided in RFC-004 D-15 (spoken languages match the backend). Remove this skip in #17.
    const knownGaps = {'language': 'Backend has 22 languages the app lacks: eros-app#17'};

    for (final entry in parsers.entries) {
      test('${entry.key} parses in the app', skip: knownGaps[entry.key], () {
        final unparsed = of(entry.key).where((name) {
          try {
            entry.value(name);
            return false;
          } on ArgumentError {
            return true;
          }
        }).toList();

        expect(unparsed, isEmpty, reason: 'backend ${entry.key} values the app can\'t read');
      });
    }
  });
}
